        readonly CheckBox color=new CheckBox{Name="GroupChangeColor",Text="Đổi màu tất cả đường khớp nhãn",AutoSize=true};readonly ComboBox colorMode=new ComboBox{Name="GroupColorMode",DropDownStyle=ComboBoxStyle.DropDownList};readonly NumericUpDown aci=new NumericUpDown{Name="GroupACI",Minimum=1,Maximum=255,Value=7,Width=80};
        readonly CheckBox scale=new CheckBox{Name="GroupChangeScale",Text="Đổi Scale tất cả đường khớp nhãn",AutoSize=true};readonly ComboBox scaleMode=new ComboBox{Name="GroupScaleMode",DropDownStyle=ComboBoxStyle.DropDownList};readonly NumericUpDown scaleValue=new NumericUpDown{Name="GroupScale",Minimum=.000000001M,Maximum=1000000,DecimalPlaces=9,Value=1,Width=180};
        readonly CheckBox width=new CheckBox{Name="GroupChangeWidth",Text="Đổi Global Width (polyline 2D)",AutoSize=true};readonly NumericUpDown widthValue=new NumericUpDown{Name="GroupWidth",Minimum=0,Maximum=1000000000,DecimalPlaces=6,Width=180};BatchEdit pattern=new BatchEdit();
        public LabelEditForm(List<LabelMember> members,List<DrawingLayerInfo> definitions,Func<int,int?> palette,ScaleContext settings,string scope,bool forceR=false)
        {
            Text="Mr.T Áp dụng cho cả cụm nhãn | 2.0.1.8";Font=UiStyle.Body();AutoScaleMode=AutoScaleMode.Dpi;Size=new Size(950,720);MinimumSize=new Size(920,700);StartPosition=FormStartPosition.CenterParent;BackColor=Color.FromArgb(245,247,250);
            var types=new HashSet<string>(members.Select(m=>m.Type),StringComparer.OrdinalIgnoreCase);var sources=definitions.Where(d=>types.Contains(d.LinetypeName)).ToList();var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(20),ColumnCount=1,RowCount=8};foreach(int h in new[]{95,72,68,68,68,74})root.RowStyles.Add(new RowStyle(SizeType.Absolute,h));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,48));Controls.Add(root);
