            scaleMode.Items.AddRange(new object[]{"Đặt mọi đường bằng giá trị này","Nhân Scale hiện tại của mỗi đường"});scaleMode.SelectedIndex=0;scaleMode.Width=320;root.Controls.Add(Panel(scale,new Control[]{scaleMode,scaleValue}),0,3);scale.CheckedChanged+=delegate{scaleMode.Enabled=scaleValue.Enabled=scale.Checked;};scaleMode.Enabled=scaleValue.Enabled=false;
