            var extras=new FlowLayoutPanel{Dock=DockStyle.Fill};var paper=new Button{Name="GroupPaper",Text="Gợi ý A0–A4 / Scale và Width…",AutoSize=true};paper.Click+=delegate{using(var dialog=new ScaleForm(sources,members.Count,settings??new ScaleContext(),true,sources.FirstOrDefault()))if(dialog.ShowDialog(this)==DialogResult.OK){scale.Checked=dialog.Value.ApplyScale;if(scale.Checked){scaleMode.SelectedIndex=0;scaleValue.Value=(decimal)dialog.Value.EntityScale;}width.Checked=dialog.Value.ApplyWidth;if(width.Checked)widthValue.Value=(decimal)dialog.Value.GlobalWidth;}};extras.Controls.Add(paper);
            var advanced=new Button{Name="GroupPattern",Text="Chữ / font / thông số nét…",AutoSize=true};var status=new Label{Name="GroupPatternStatus",Text="Giữ chữ, font và thông số nét nguồn.",AutoSize=true};advanced.Click+=delegate{using(var dialog=new BatchEditForm(sources,sources,null)){dialog.RestrictToPatterns();if(dialog.ShowDialog(this)==DialogResult.OK){pattern=dialog.Value;status.Text="Đã chọn thông số nét nâng cao; sẽ xem trước trước khi ghi.";}}};extras.Controls.Add(advanced);var reset=new Button{Name="GroupClearPattern",Text="Giữ nét nguồn",AutoSize=true};reset.Click+=delegate{pattern=new BatchEdit();status.Text="Giữ chữ, font và thông số nét nguồn.";};extras.Controls.Add(reset);extras.Controls.Add(status);root.Controls.Add(extras,0,5);
            root.Controls.Add(new Label{Text="R=0 dùng chữ native trong linetype; REVERSE có tác dụng. Không tự ép mọi nhánh polyline cùng chiều đọc.\r\nChọn R=0 sẽ gỡ đúng nhãn MText liên kết cũ của tool và đưa đường về nét native.\r\nMàu/Scale/Width/Linetype áp trực tiếp lên đường; Layer, hình học và thuộc tính chưa chọn giữ nguyên.\r\nĐường khóa/không hỗ trợ sẽ được báo trước khi áp dụng. Không vào định nghĩa block/Xref.\r\nworkflow by Mr.Toan-NhiTW",Dock=DockStyle.Fill},0,6);
