            root.Controls.Add(new TextBox{Name="LabelPlanSummary",Text=summary,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill},0,0);var grid=new DataGridView{Name="LabelReviewGrid",ReadOnly=true,Dock=DockStyle.Fill,AllowUserToAddRows=false,RowHeadersVisible=false,AutoGenerateColumns=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};UiStyle.Grid(grid);foreach(var s in new[]{new[]{"Handle","Đường","80"},new[]{"Label","Nhãn","115"},new[]{"Layer","Layer giữ nguyên","200"},new[]{"Before","Trước","300"},new[]{"After","Sau","360"}})grid.Columns.Add(new DataGridViewTextBoxColumn{DataPropertyName=s[0],HeaderText=s[1],MinimumWidth=Int32.Parse(s[2])});grid.DataSource=rows;root.Controls.Add(grid,0,1);var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft};buttons.Controls.Add(new Button{Name="ApplyLabelGroup",Text="Áp dụng cho "+rows.Count+" đường",AutoSize=true,Enabled=rows.Count>0,DialogResult=DialogResult.OK});buttons.Controls.Add(new Button{Name="CancelLabelReview",Text="Quay lại / Hủy",AutoSize=true,DialogResult=DialogResult.Cancel});root.Controls.Add(buttons,0,2);
